import { test } from "node:test";
import assert from "node:assert/strict";
import { cartTotal } from "../src/cart.ts";

test("an empty cart costs nothing", () => {
  assert.equal(cartTotal({ market: "se", lines: [] }), 0);
});

test("one line adds VAT", () => {
  assert.equal(cartTotal({ market: "se", lines: [{ sku: "a", price: 100, quantity: 1 }] }), 125);
});

test("cart total counts each line's quantity", () => {
  assert.equal(cartTotal({ market: "se", lines: [{ sku: "a", price: 300, quantity: 3 }] }), 1125);
